import { OpsRestaurantSettingsClient } from '@/components/features/restaurant-settings/OpsRestaurantSettingsClient';

import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Google Business Profile · Nab a Table Ops',
  description: 'Connect a Google account and link the correct GBP location to this restaurant.',
};

export default function GoogleBusinessProfileSettingsPage() {
  return <OpsRestaurantSettingsClient view="google-business-profile" />;
}

'use client';

import dynamic from 'next/dynamic';
import { useEffect, type ReactNode } from 'react';

import { OpsEmptyState } from '@/components/features/ops-shell/patterns/OpsEmptyState';
import { Skeleton } from '@/components/ui/skeleton';
import { useOpsActiveMembership, useOpsSession } from '@/contexts/ops-session';

import type { RestaurantSettingsView } from './types';

const SettingsSectionSkeleton = ({ title }: { title: string }) => (
  <div className="rounded-lg border border-border/60 bg-muted/30 p-6" aria-busy="true" role="status">
    <p className="text-sm font-medium text-foreground">{title}</p>
    <div className="mt-3 space-y-3">
      <Skeleton className="h-4 w-40" />
      <Skeleton className="h-10 w-full" />
      <Skeleton className="h-10 w-3/4" />
    </div>
  </div>
);

const RestaurantProfileSection = dynamic(() => import('./RestaurantProfileSection').then((m) => m.RestaurantProfileSection), {
  loading: () => <SettingsSectionSkeleton title="Loading profile" />,
});

const GoogleBusinessProfileSection = dynamic(
  () =>
    import('./google-business-profile/GoogleBusinessProfileSection').then(
      (m) => m.GoogleBusinessProfileSection,
    ),
  {
    loading: () => <SettingsSectionSkeleton title="Loading Google Business Profile" />,
  },
);

const AvailabilityOccasionsCommandCenter = dynamic(
  () =>
    import('./AvailabilityOccasionsCommandCenter').then((m) => m.AvailabilityOccasionsCommandCenter),
  {
    loading: () => <SettingsSectionSkeleton title="Loading availability and occasions" />,
  },
);

const OpsTeamManagementClient = dynamic(() => import('../team').then((m) => m.OpsTeamManagementClient), {
  loading: () => <SettingsSectionSkeleton title="Loading team" />,
});

export type OpsRestaurantSettingsClientProps = {
  defaultRestaurantId?: string | null;
  view: RestaurantSettingsView;
};

export function OpsRestaurantSettingsClient({ defaultRestaurantId, view }: OpsRestaurantSettingsClientProps) {
  const { memberships, activeRestaurantId, setActiveRestaurantId } = useOpsSession();
  const activeMembership = useOpsActiveMembership();

  useEffect(() => {
    if (activeRestaurantId) {
      return;
    }
    if (defaultRestaurantId) {
      setActiveRestaurantId(defaultRestaurantId);
      return;
    }
    if (memberships[0]) {
      setActiveRestaurantId(memberships[0].restaurantId);
    }
  }, [activeRestaurantId, defaultRestaurantId, memberships, setActiveRestaurantId]);

  if (memberships.length === 0) {
    return (
      <section className="mx-auto flex min-h-[60vh] max-w-2xl items-center justify-center p-8">
        <OpsEmptyState
          title="No restaurant access"
          description="You need access to at least one restaurant to manage settings. Contact an owner or admin for access."
        />
      </section>
    );
  }

  const selectedMembership =
    activeMembership ??
    memberships.find((membership) => membership.restaurantId === activeRestaurantId) ??
    memberships[0] ??
    null;

  const selectedRestaurantId = selectedMembership?.restaurantId ?? null;

  const renderByView: Record<RestaurantSettingsView, (context: { restaurantId: string | null }) => ReactNode> = {
    profile: ({ restaurantId }) => <RestaurantProfileSection restaurantId={restaurantId} />,
    'google-business-profile': ({ restaurantId }) => (
      <GoogleBusinessProfileSection restaurantId={restaurantId} />
    ),
    availability: ({ restaurantId }) => <AvailabilityOccasionsCommandCenter restaurantId={restaurantId} />,
    team: () => <OpsTeamManagementClient />,
  };

  return <div className="space-y-6">{renderByView[view]({ restaurantId: selectedRestaurantId })}</div>;
}

'use client';

import { useSearchParams } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import {
  useOpsCreateGoogleBusinessProfileDraft,
  useOpsDisconnectGoogleBusinessProfile,
  useOpsGoogleBusinessProfileConnection,
  useOpsLinkGoogleBusinessProfileLocation,
} from '@/hooks/ops/useOpsGoogleBusinessProfile';
import { useOpsOperatingHours } from '@/hooks/ops/useOpsOperatingHours';
import { useOpsRestaurantDetails } from '@/hooks/ops/useOpsRestaurantDetails';
import { useOpsServicePeriods } from '@/hooks/ops/useOpsServicePeriods';
import {
  OPS_RESTAURANTS_BASE,
  type GoogleBusinessProfileAvailableLocation,
} from '@/services/ops/restaurants';

import { AlignmentCard } from './components/AlignmentCard';
import { ConnectCard } from './components/ConnectCard';
import { GoogleBusinessProfileSyncPageShell } from './components/GoogleBusinessProfileSyncPageShell';
import { LocationPickerCard } from './components/LocationPickerCard';
import { PageHeader } from './components/PageHeader';
import { SnapshotCard } from './components/SnapshotCard';
import { deriveProfileVerification } from './googleBusinessProfileVerification';
import { buildDriftReport } from './lib/drift';

type GoogleBusinessProfileSectionProps = {
  restaurantId: string | null;
};

function buildLocationValue(location: GoogleBusinessProfileAvailableLocation): string {
  return JSON.stringify({
    accountName: location.accountName,
    accountId: location.accountId,
    locationName: location.locationName,
    locationId: location.locationId,
  });
}

function LoadingSkeleton() {
  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <Skeleton className="h-8 w-64" />
        <Skeleton className="h-4 w-48" />
      </div>
      <Skeleton className="h-56 w-full rounded-lg" />
    </div>
  );
}

export function GoogleBusinessProfileSection({ restaurantId }: GoogleBusinessProfileSectionProps) {
  const searchParams = useSearchParams();
  const connectionQuery = useOpsGoogleBusinessProfileConnection(restaurantId);
  const profileQuery = useOpsRestaurantDetails(restaurantId);
  const operatingHoursQuery = useOpsOperatingHours(restaurantId);
  const servicePeriodsQuery = useOpsServicePeriods(restaurantId);
  const linkMutation = useOpsLinkGoogleBusinessProfileLocation(restaurantId);
  const disconnectMutation = useOpsDisconnectGoogleBusinessProfile(restaurantId);
  const createDraftMutation = useOpsCreateGoogleBusinessProfileDraft(restaurantId);

  const [selectedLocationValue, setSelectedLocationValue] = useState('');
  const [wantsRelink, setWantsRelink] = useState(false);

  useEffect(() => {
    const gbpStatus = searchParams.get('gbp');
    const message = searchParams.get('message');
    if (!gbpStatus) {
      return;
    }

    if (gbpStatus === 'connected') {
      toast.success('Google Business Profile connected. Choose a location to finish linking.');
    } else if (gbpStatus === 'error') {
      toast.error(message ?? 'Google Business Profile connection failed.');
    }

    if (typeof window !== 'undefined') {
      const url = new URL(window.location.href);
      url.searchParams.delete('gbp');
      url.searchParams.delete('message');
      window.history.replaceState({}, '', url.toString());
    }
  }, [searchParams]);

  const data = connectionQuery.data;

  useEffect(() => {
    if (!data) {
      return;
    }

    if (data.externalLocationName && data.externalAccountName && !wantsRelink) {
      const linkedLocation = data.availableLocations.find(
        (location) =>
          location.locationName === data.externalLocationName &&
          location.accountName === data.externalAccountName,
      );
      if (linkedLocation) {
        setSelectedLocationValue(buildLocationValue(linkedLocation));
        return;
      }
    }

    if (!selectedLocationValue && data.availableLocations[0]) {
      setSelectedLocationValue(buildLocationValue(data.availableLocations[0]));
    }
  }, [data, selectedLocationValue, wantsRelink]);

  const selectedLocation = useMemo<GoogleBusinessProfileAvailableLocation | null>(() => {
    if (!data) {
      return null;
    }

    return (
      data.availableLocations.find(
        (location) => buildLocationValue(location) === selectedLocationValue,
      ) ?? null
    );
  }, [data, selectedLocationValue]);

  if (!restaurantId) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-sm text-muted-foreground">
          Select a restaurant using the sidebar switcher to manage its Google Business Profile
          connection.
        </CardContent>
      </Card>
    );
  }

  if (connectionQuery.isLoading && !data) {
    return <LoadingSkeleton />;
  }

  if (connectionQuery.error) {
    return (
      <Card>
        <CardContent className="py-6">
          <Alert variant="destructive">
            <AlertTitle>Unable to load Google Business Profile</AlertTitle>
            <AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <span>{connectionQuery.error.message}</span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => void connectionQuery.refetch()}
              >
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </CardContent>
      </Card>
    );
  }

  if (!data) {
    return null;
  }

  const connectHref = `${OPS_RESTAURANTS_BASE}/${restaurantId}/google-business-profile/connect`;
  const manageOnGoogleHref = data.externalPlaceId
    ? `https://www.google.com/maps/search/?api=1&query_place_id=${encodeURIComponent(data.externalPlaceId)}`
    : null;
  const hasLinkedLocation = Boolean(data.externalLocationId);
  const isLinked = data.status === 'linked' || data.status === 'sync_error';
  const showPicker =
    data.status === 'authorized' || data.status === 'reauth_required' || (isLinked && wantsRelink);
  const showConnect = !isLinked && !showPicker && data.status !== 'authorized';
  const showChangeLocation = data.availableLocations.length > 1;

  const handleLinkLocation = () => {
    if (!selectedLocation) {
      toast.error('Choose a location before linking.');
      return;
    }

    linkMutation.mutate(
      {
        accountName: selectedLocation.accountName,
        accountId: selectedLocation.accountId,
        locationName: selectedLocation.locationName,
        locationId: selectedLocation.locationId,
      },
      {
        onSuccess: () => {
          setWantsRelink(false);
          toast.success('Google Business Profile location linked.');
        },
        onError: (error) => toast.error(error.message),
      },
    );
  };

  const handleDisconnect = () => {
    disconnectMutation.mutate(undefined, {
      onSuccess: () => {
        setSelectedLocationValue('');
        setWantsRelink(false);
        toast.success('Google Business Profile disconnected.');
      },
      onError: (error) => toast.error(error.message),
    });
  };

  return (
    <div className="space-y-6">
      <PageHeader
        status={data.status}
        lastPullAt={data.lastPullAt}
        onRefresh={() => void connectionQuery.refetch()}
        isRefreshing={connectionQuery.isFetching}
        manageOnGoogleHref={manageOnGoogleHref}
        canDisconnect={data.status !== 'unlinked'}
        onDisconnect={handleDisconnect}
        isDisconnecting={disconnectMutation.isPending}
      />

      {showConnect ? (
        <ConnectCard
          connectHref={connectHref}
          isConfigured={data.isConfigured}
          isPendingAuth={data.status === 'pending_auth'}
          lastError={!isLinked ? data.lastError : null}
        />
      ) : null}

      {showPicker ? (
        <LocationPickerCard
          data={data}
          connectHref={connectHref}
          selectedLocation={selectedLocation}
          selectedLocationValue={selectedLocationValue}
          onSelectedLocationValueChange={setSelectedLocationValue}
          buildLocationValue={buildLocationValue}
          onLinkLocation={handleLinkLocation}
          isLinking={linkMutation.isPending}
          hasLinkedLocation={hasLinkedLocation}
        />
      ) : null}

      {isLinked ? (
        <>
          <GoogleBusinessProfileSyncPageShell
            restaurantId={restaurantId}
            connection={data}
            manageOnGoogleHref={manageOnGoogleHref}
            onGenerateDraft={() =>
              createDraftMutation.mutate(undefined, {
                onSuccess: () => toast.success('GBP review draft generated.'),
                onError: (error) => toast.error(error.message),
              })
            }
            onChangeLocation={() => setWantsRelink(true)}
            isGeneratingDraft={createDraftMutation.isPending}
            showChangeLocation={showChangeLocation}
          />

          <section
            aria-label="Secondary analysis"
            className="space-y-4 rounded-lg border border-dashed border-border bg-muted/20 p-4"
            data-testid="gbp-secondary-analysis"
          >
            <div className="space-y-1">
              <h2 className="text-sm font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                Secondary analysis
              </h2>
              <p className="text-xs text-muted-foreground">
                Reference alignment and snapshot data for deeper operational review.
              </p>
            </div>
            <AlignmentCard
              report={buildDriftReport({
                profile: profileQuery.data,
                connection: data,
                verification: deriveProfileVerification({
                  profile: profileQuery.data,
                  connection: data,
                }),
              })}
              connection={data}
              operatingHours={operatingHoursQuery.data}
              servicePeriods={servicePeriodsQuery.data}
              isScheduleDataLoading={
                (operatingHoursQuery.isLoading && !operatingHoursQuery.data) ||
                (servicePeriodsQuery.isLoading && !servicePeriodsQuery.data)
              }
            />
            <SnapshotCard businessInfo={data.businessInfo} />
          </section>
        </>
      ) : null}
    </div>
  );
}

'use client';

import { AlertTriangle, GitPullRequestArrow, ShieldAlert } from 'lucide-react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';

import { AuditTimeline } from './AuditTimeline';
import { DifferenceDetailPanel } from './DifferenceDetailPanel';
import { DifferenceInbox } from './DifferenceInbox';
import { PreflightReviewDialog } from './PreflightReviewDialog';
import { PublishPasswordDialog } from './PublishPasswordDialog';
import { RetryGooglePushPanel } from './RetryGooglePushPanel';
import { SyncDirectionTabs } from './SyncDirectionTabs';
import { SyncStatusHeader } from './SyncStatusHeader';
import { buildDirectionStats, directionLabel } from '../lib/sync-review';
import { useGoogleBusinessProfileSyncWorkspace } from '../lib/useGoogleBusinessProfileSyncWorkspace';

import type { GoogleBusinessProfileConnection } from '@/services/ops/restaurants';

type GoogleBusinessProfileSyncPageShellProps = {
  restaurantId: string;
  connection: GoogleBusinessProfileConnection;
  manageOnGoogleHref: string | null;
  onGenerateDraft: () => void;
  onChangeLocation: () => void;
  isGeneratingDraft: boolean;
  showChangeLocation: boolean;
};

function applyDialogTitle(direction: 'google_to_nabatable' | 'nabatable_to_google') {
  return direction === 'google_to_nabatable'
    ? 'Apply changes to Nabatable'
    : 'Apply changes to Google';
}

export function GoogleBusinessProfileSyncPageShell({
  restaurantId,
  connection,
  manageOnGoogleHref,
  onGenerateDraft,
  onChangeLocation,
  isGeneratingDraft,
  showChangeLocation,
}: GoogleBusinessProfileSyncPageShellProps) {
  const workspace = useGoogleBusinessProfileSyncWorkspace(restaurantId);
  const workflow = workspace.workflowQuery.data;
  const draft = workspace.draft;
  const googlePushEnabled = connection.pushEnabled;
  const pushDirectionBlocked = workspace.direction === 'nabatable_to_google' && !googlePushEnabled;
  const statsByDirection = {
    google_to_nabatable: buildDirectionStats(
      draft,
      workspace.fieldDecisions,
      'google_to_nabatable',
    ),
    nabatable_to_google: buildDirectionStats(
      draft,
      workspace.fieldDecisions,
      'nabatable_to_google',
    ),
  };

  const conflictMetadata =
    draft?.conflictMetadata &&
    typeof draft.conflictMetadata === 'object' &&
    !Array.isArray(draft.conflictMetadata)
      ? (draft.conflictMetadata as Record<string, unknown>)
      : null;
  const staleFieldKeys = Array.isArray(conflictMetadata?.staleFieldKeys)
    ? (conflictMetadata?.staleFieldKeys as string[])
    : [];

  return (
    <div className="min-w-0 space-y-4">
      <SyncStatusHeader
        connection={connection}
        workflow={workflow}
        manageOnGoogleHref={manageOnGoogleHref}
        onGenerateDraft={onGenerateDraft}
        onChangeLocation={onChangeLocation}
        isGeneratingDraft={isGeneratingDraft}
        showChangeLocation={showChangeLocation}
      />

      {workflow?.blockedReasons.length ? (
        <Alert>
          <ShieldAlert className="size-4" />
          <AlertTitle>Review notes</AlertTitle>
          <AlertDescription>{workflow.blockedReasons[0]}</AlertDescription>
        </Alert>
      ) : null}

      {draft?.status === 'stale' && staleFieldKeys.length > 0 ? (
        <Alert variant="destructive">
          <AlertTriangle className="size-4" />
          <AlertTitle>Changes need another check</AlertTitle>
          <AlertDescription>
            Check for changes again before applying updates. Changed fields:{' '}
            {staleFieldKeys.join(', ')}.
          </AlertDescription>
        </Alert>
      ) : null}

      <SyncDirectionTabs
        direction={workspace.direction}
        onDirectionChange={workspace.setDirection}
        stats={statsByDirection}
        hasMixedSelections={workspace.mixedDirectionSelections}
        googlePushEnabled={googlePushEnabled}
      />

      {!googlePushEnabled ? (
        <Alert>
          <ShieldAlert className="size-4" />
          <AlertTitle>Google updates are disabled</AlertTitle>
          <AlertDescription>
            This linked Business Profile can still be reviewed and pulled into Nabatable, but Google
            write-back is disabled for this location.
          </AlertDescription>
        </Alert>
      ) : null}

      <Card className="min-w-0 border-border/70 shadow-sm">
        <CardContent className="min-w-0 space-y-4 p-3 sm:p-4">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
            <div className="space-y-1">
              <h2 className="text-base font-semibold text-foreground">
                {directionLabel(workspace.direction)} review
              </h2>
              <p className="text-sm text-muted-foreground">
                Choose which fields to use, then run a final check for this update path.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-2 sm:justify-end">
              <Button
                type="button"
                className="w-full sm:w-auto"
                disabled={
                  !draft ||
                  pushDirectionBlocked ||
                  statsByDirection[workspace.direction].selectedCount === 0
                }
                onClick={() => {
                  workspace.resetPreflight();
                  workspace.setPreflightDialogOpen(true);
                }}
              >
                Review selected changes ({statsByDirection[workspace.direction].selectedCount})
              </Button>
            </div>
          </div>

          {!draft ? (
            <div className="flex min-h-[360px] items-center justify-center rounded-lg border border-dashed border-border/70 bg-muted/20 p-8 text-center">
              <div className="space-y-3">
                <div className="mx-auto flex size-16 items-center justify-center rounded-full bg-background shadow-sm">
                  <GitPullRequestArrow className="size-7 text-muted-foreground" />
                </div>
                <div className="space-y-1">
                  <p className="text-base font-semibold text-foreground">No changes checked yet</p>
                  <p className="text-sm text-muted-foreground">
                    Check for changes to compare the latest Google profile details with Nabatable.
                  </p>
                </div>
              </div>
            </div>
          ) : (
            <div className="grid min-h-[560px] min-w-0 grid-cols-1 overflow-hidden rounded-lg border border-border/70 lg:grid-cols-[minmax(260px,320px)_minmax(0,1fr)]">
              <div className="min-w-0 border-b border-border/60 lg:border-b-0 lg:border-r">
                <DifferenceInbox
                  summaries={workspace.sectionSummaries}
                  selectedSectionKey={workspace.selectedSectionKey}
                  onSelect={workspace.setSelectedSectionKey}
                />
              </div>
              <div className="min-w-0">
                <DifferenceDetailPanel
                  summary={workspace.selectedSectionSummary}
                  getDecisionForItem={(fieldKey) =>
                    workspace.fieldDecisions[fieldKey] ?? 'keep_nabatable'
                  }
                  onDecisionChange={(fieldKey, decision) => {
                    const section = draft.sectionDiffs.find((candidate) =>
                      candidate.items.some((item) => item.fieldKey === fieldKey),
                    );
                    const item = section?.items.find(
                      (candidate) => candidate.fieldKey === fieldKey,
                    );
                    if (!item) {
                      return;
                    }
                    workspace.updateDecision(item, decision);
                  }}
                  activePublishJob={workspace.activePublishJob}
                  googlePushEnabled={googlePushEnabled}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <RetryGooglePushPanel
        activePublishJob={workspace.activePublishJob}
        onRetry={() => workspace.setRetryDialogOpen(true)}
        isRetryPending={workspace.retryMutation.isPending}
      />

      <AuditTimeline events={workflow?.auditEvents ?? []} />

      <PreflightReviewDialog
        open={workspace.preflightDialogOpen}
        onOpenChange={workspace.setPreflightDialogOpen}
        direction={workspace.direction}
        selectedItems={workspace.selectedItems}
        preflight={workspace.preflightResult}
        preflightErrorMessage={
          workspace.preflightErrorMessage ?? workspace.preflightMutation.error?.message ?? null
        }
        isPreflightPending={workspace.preflightMutation.isPending}
        onRunPreflight={async () => {
          await workspace.runPreflight().catch(() => undefined);
        }}
        onContinue={() => workspace.setPublishDialogOpen(true)}
      />

      <PublishPasswordDialog
        open={workspace.publishDialogOpen}
        onOpenChange={workspace.setPublishDialogOpen}
        title={applyDialogTitle(workspace.direction)}
        description="Password confirmation is required after the final check passes."
        confirmLabel="Apply reviewed changes"
        isPending={workspace.publishMutation.isPending}
        errorMessage={workspace.publishErrorMessage}
        onConfirm={async (password) => {
          await workspace.publishWithPassword(password).catch(() => undefined);
        }}
      />

      <PublishPasswordDialog
        open={workspace.retryDialogOpen}
        onOpenChange={workspace.setRetryDialogOpen}
        title="Retry Google update"
        description="Retry only the Google update from the last reviewed change."
        confirmLabel="Retry Google update"
        isPending={workspace.retryMutation.isPending}
        errorMessage={workspace.retryErrorMessage}
        onConfirm={async (password) => {
          await workspace.retryGooglePushWithPassword(password).catch(() => undefined);
        }}
      />
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import {
  useOpsGoogleBusinessProfileWorkflow,
  useOpsPreflightGoogleBusinessProfileDraftPublish,
  useOpsPublishGoogleBusinessProfileDraft,
  useOpsRetryGoogleBusinessProfileDraftGooglePush,
  useOpsUpdateGoogleBusinessProfileDraft,
} from '@/hooks/ops/useOpsGoogleBusinessProfile';
import { HttpError } from '@/lib/http/errors';

import {
  buildDirectionSectionSummaries,
  buildDirectionStats,
  buildSelectedApprovalsForDirection,
  buildSelectedItemsForDirection,
  compareBooleanRecords,
  countSelectionsByDirection,
  deriveInitialFieldDecisions,
  getFieldDecision,
  hasMixedDirectionSelections,
  isReadOnlyReviewStatus,
  type FieldDecision,
  type SyncPublishDirection,
} from './sync-review';

import type {
  GoogleBusinessProfileDraftItem,
  GoogleBusinessProfileDraftPublishPreflight,
} from '@/services/ops/restaurants';

function errorMessage(error: unknown, fallback: string): string {
  if (error instanceof Error && error.message.trim()) {
    return error.message;
  }

  return fallback;
}

function shouldRefreshWorkflow(error: unknown): boolean {
  return (
    error instanceof HttpError &&
    [
      'GBP_DRAFT_STALE',
      'GBP_DRAFT_INVALID_STATE',
      'GBP_DRAFT_NOT_APPROVED',
      'GBP_PUBLISH_JOB_INVALID_STATE',
      'GBP_PUBLISH_JOB_MISMATCH',
    ].includes(error.code)
  );
}

export function useGoogleBusinessProfileSyncWorkspace(restaurantId: string) {
  const workflowQuery = useOpsGoogleBusinessProfileWorkflow(restaurantId);
  const updateDraftMutation = useOpsUpdateGoogleBusinessProfileDraft(restaurantId);
  const preflightMutation = useOpsPreflightGoogleBusinessProfileDraftPublish(restaurantId);
  const publishMutation = useOpsPublishGoogleBusinessProfileDraft(restaurantId);
  const retryMutation = useOpsRetryGoogleBusinessProfileDraftGooglePush(restaurantId);

  const draft = workflowQuery.data?.latestDraft ?? null;
  const activePublishJob = workflowQuery.data?.activePublishJob ?? null;

  const [direction, setDirection] = useState<SyncPublishDirection>('google_to_nabatable');
  const [fieldDecisions, setFieldDecisions] = useState<Record<string, FieldDecision>>(() =>
    deriveInitialFieldDecisions(draft),
  );
  const [selectedSectionKey, setSelectedSectionKey] = useState<string | null>(null);
  const [preflightDialogOpen, setPreflightDialogOpen] = useState(false);
  const [publishDialogOpen, setPublishDialogOpen] = useState(false);
  const [retryDialogOpen, setRetryDialogOpen] = useState(false);
  const [preflightResult, setPreflightResult] =
    useState<GoogleBusinessProfileDraftPublishPreflight | null>(null);
  const [preflightErrorMessage, setPreflightErrorMessage] = useState<string | null>(null);
  const [publishErrorMessage, setPublishErrorMessage] = useState<string | null>(null);
  const [retryErrorMessage, setRetryErrorMessage] = useState<string | null>(null);

  const previousDraftIdRef = useRef<string | null>(draft?.id ?? null);

  useEffect(() => {
    if (activePublishJob?.directionIntent === 'nabatable_to_google') {
      setDirection('nabatable_to_google');
    } else {
      setDirection('google_to_nabatable');
    }

    const currentDraftId = draft?.id ?? null;
    if (previousDraftIdRef.current === currentDraftId) {
      return;
    }

    previousDraftIdRef.current = currentDraftId;
    setFieldDecisions(deriveInitialFieldDecisions(draft));
    setSelectedSectionKey(null);
    setPreflightResult(null);
    setPreflightErrorMessage(null);
    setPublishErrorMessage(null);
    setRetryErrorMessage(null);
  }, [activePublishJob?.directionIntent, draft]);

  const selectedApprovals = useMemo(
    () => buildSelectedApprovalsForDirection(draft, fieldDecisions, direction),
    [draft, fieldDecisions, direction],
  );

  const sectionSummaries = useMemo(
    () => buildDirectionSectionSummaries(draft, fieldDecisions, direction),
    [draft, fieldDecisions, direction],
  );

  const selectedSectionSummary = useMemo(
    () =>
      sectionSummaries.find((summary) => summary.section.sectionKey === selectedSectionKey) ?? null,
    [sectionSummaries, selectedSectionKey],
  );

  const selectedItems = useMemo(
    () => buildSelectedItemsForDirection(draft, fieldDecisions, direction),
    [draft, fieldDecisions, direction],
  );

  const directionStats = useMemo(
    () => buildDirectionStats(draft, fieldDecisions, direction),
    [draft, fieldDecisions, direction],
  );

  const directionCounts = useMemo(
    () => countSelectionsByDirection(draft, fieldDecisions),
    [draft, fieldDecisions],
  );

  const mixedDirectionSelections = useMemo(
    () => hasMixedDirectionSelections(draft, fieldDecisions),
    [draft, fieldDecisions],
  );

  useEffect(() => {
    if (
      selectedSectionKey &&
      sectionSummaries.some((summary) => summary.section.sectionKey === selectedSectionKey)
    ) {
      return;
    }

    setSelectedSectionKey(sectionSummaries[0]?.section.sectionKey ?? null);
  }, [sectionSummaries, selectedSectionKey]);

  const resetPreflight = useCallback(() => {
    setPreflightResult(null);
    setPreflightErrorMessage(null);
    setPublishErrorMessage(null);
    preflightMutation.reset();
  }, [preflightMutation]);

  const updateDecision = useCallback(
    (item: GoogleBusinessProfileDraftItem, decision: FieldDecision) => {
      resetPreflight();
      setFieldDecisions((current) => ({
        ...current,
        [item.fieldKey]: decision,
      }));
    },
    [resetPreflight],
  );

  const ensureDraftSelectionsApproved = useCallback(async () => {
    if (!draft) {
      throw new Error('Generate a workflow draft before continuing.');
    }

    if (isReadOnlyReviewStatus(draft.status)) {
      await workflowQuery.refetch();
      throw new Error(
        'This Google Business Profile review has already been applied. Check for changes again before continuing.',
      );
    }

    const needsUpdate =
      draft.status !== 'approved' ||
      !compareBooleanRecords(draft.selectedApprovals, selectedApprovals);

    if (!needsUpdate) {
      return;
    }

    await updateDraftMutation.mutateAsync({
      draftId: draft.id,
      payload: {
        selectedApprovals,
        status: 'approved',
      },
    });
  }, [draft, selectedApprovals, updateDraftMutation, workflowQuery]);

  const runPreflight = useCallback(async () => {
    if (!draft) {
      throw new Error('Generate a workflow draft before continuing.');
    }

    setPreflightErrorMessage(null);
    setPublishErrorMessage(null);

    try {
      await ensureDraftSelectionsApproved();
      const result = await preflightMutation.mutateAsync({
        draftId: draft.id,
        payload: {
          selectedApprovals,
          directionIntent: direction,
        },
      });
      setPreflightResult(result);
      return result;
    } catch (error) {
      if (shouldRefreshWorkflow(error)) {
        void workflowQuery.refetch();
      }
      setPreflightErrorMessage(
        errorMessage(error, 'Unable to run the final Google Business Profile check.'),
      );
      throw error;
    }
  }, [
    draft,
    direction,
    ensureDraftSelectionsApproved,
    preflightMutation,
    selectedApprovals,
    workflowQuery,
  ]);

  const publishWithPassword = useCallback(
    async (password: string) => {
      if (!draft || !preflightResult) {
        throw new Error('Run the final check before applying changes.');
      }

      setPublishErrorMessage(null);

      try {
        if (isReadOnlyReviewStatus(draft.status)) {
          await workflowQuery.refetch();
          throw new Error(
            'This Google Business Profile review has already been applied. Check for changes again before continuing.',
          );
        }

        await publishMutation.mutateAsync({
          draftId: draft.id,
          payload: {
            password,
            publishJobId: preflightResult.publishJobId,
            idempotencyKey: preflightResult.idempotencyKey,
            selectedApprovals,
            directionIntent: direction,
          },
        });
        setPublishDialogOpen(false);
        setPreflightDialogOpen(false);
        setPreflightResult(null);
        await workflowQuery.refetch();
      } catch (error) {
        if (shouldRefreshWorkflow(error)) {
          void workflowQuery.refetch();
        }
        const message = errorMessage(error, 'Unable to publish Google Business Profile changes.');
        setPublishErrorMessage(message);
        throw error;
      }
    },
    [direction, draft, preflightResult, publishMutation, selectedApprovals, workflowQuery],
  );

  const retryGooglePushWithPassword = useCallback(
    async (password: string) => {
      if (!draft || !activePublishJob) {
        throw new Error('No retryable Google push is available.');
      }

      setRetryErrorMessage(null);

      try {
        await retryMutation.mutateAsync({
          draftId: draft.id,
          publishJobId: activePublishJob.id,
          payload: { password },
        });
        setRetryDialogOpen(false);
        await workflowQuery.refetch();
      } catch (error) {
        if (shouldRefreshWorkflow(error)) {
          void workflowQuery.refetch();
        }
        const message = errorMessage(error, 'Unable to retry the Google push.');
        setRetryErrorMessage(message);
        throw error;
      }
    },
    [activePublishJob, draft, retryMutation, workflowQuery],
  );

  return {
    workflowQuery,
    draft,
    activePublishJob,
    direction,
    setDirection: (value: SyncPublishDirection) => {
      resetPreflight();
      setDirection(value);
    },
    fieldDecisions,
    sectionSummaries,
    selectedSectionSummary,
    selectedSectionKey,
    setSelectedSectionKey,
    directionStats,
    directionCounts,
    mixedDirectionSelections,
    selectedApprovals,
    selectedItems,
    updateDecision,
    getDecisionForItem: (item: GoogleBusinessProfileDraftItem) =>
      getFieldDecision(item, fieldDecisions),
    preflightDialogOpen,
    setPreflightDialogOpen,
    preflightResult,
    resetPreflight,
    runPreflight,
    preflightMutation,
    preflightErrorMessage,
    publishDialogOpen,
    setPublishDialogOpen,
    publishErrorMessage,
    publishMutation,
    publishWithPassword,
    retryDialogOpen,
    setRetryDialogOpen,
    retryErrorMessage,
    retryMutation,
    retryGooglePushWithPassword,
  };
}

import { formatGbpDay } from './formatters';

import type {
  GoogleBusinessProfileDraftItem,
  GoogleBusinessProfileDraftSection,
  GoogleBusinessProfilePublishDirectionIntent,
  GoogleBusinessProfileWorkflow,
  GoogleBusinessProfileWorkflowDraft,
} from '@/services/ops/restaurants';

export type SyncPublishDirection = Exclude<
  GoogleBusinessProfilePublishDirectionIntent,
  'google_to_nabatable_with_google_sync'
>;

export type FieldDecision =
  | 'pull_from_google'
  | 'push_to_google'
  | 'keep_nabatable'
  | 'ignore_suggestion'
  | 'manual';

export type DirectionSectionSummary = {
  section: GoogleBusinessProfileDraftSection;
  changedItems: GoogleBusinessProfileDraftItem[];
  actionableCount: number;
  selectedCount: number;
  oppositeDirectionCount: number;
  blockedCount: number;
  ignoredCount: number;
  unchangedCount: number;
};

export type DirectionStats = {
  selectedCount: number;
  actionableCount: number;
  blockedCount: number;
  ignoredCount: number;
};

const READ_ONLY_REVIEW_STATUSES = new Set(['published', 'publishing', 'archived']);

export function isReadOnlyReviewStatus(status: string | null | undefined): boolean {
  return Boolean(status && READ_ONLY_REVIEW_STATUSES.has(status));
}

export const SYNC_DIRECTION_OPTIONS: Array<{
  value: SyncPublishDirection;
  label: string;
  shortLabel: string;
  description: string;
}> = [
  {
    value: 'google_to_nabatable',
    label: 'Update Nabatable',
    shortLabel: 'Google → Nabatable',
    description: 'Use selected Google profile details in Nabatable.',
  },
  {
    value: 'nabatable_to_google',
    label: 'Update Google',
    shortLabel: 'Nabatable → Google',
    description: 'Send selected Nabatable details to Google.',
  },
];

function capitalize(value: string): string {
  if (!value) {
    return value;
  }

  return value.charAt(0).toUpperCase() + value.slice(1);
}

export function directionLabel(direction: SyncPublishDirection): string {
  return SYNC_DIRECTION_OPTIONS.find((option) => option.value === direction)?.label ?? direction;
}

export function directionShortLabel(direction: SyncPublishDirection): string {
  return (
    SYNC_DIRECTION_OPTIONS.find((option) => option.value === direction)?.shortLabel ?? direction
  );
}

export function oppositeDirection(direction: SyncPublishDirection): SyncPublishDirection {
  return direction === 'google_to_nabatable' ? 'nabatable_to_google' : 'google_to_nabatable';
}

export function isChangedItem(item: GoogleBusinessProfileDraftItem): boolean {
  return item.status !== 'unchanged';
}

export function supportsDirection(
  item: GoogleBusinessProfileDraftItem,
  direction: SyncPublishDirection,
): boolean {
  return direction === 'google_to_nabatable' ? item.canPublishToNabatable : item.canPushToGoogle;
}

export function decisionMatchesDirection(
  decision: FieldDecision,
  direction: SyncPublishDirection,
): boolean {
  return (
    (direction === 'google_to_nabatable' && decision === 'pull_from_google') ||
    (direction === 'nabatable_to_google' && decision === 'push_to_google')
  );
}

export function directionDecision(direction: SyncPublishDirection): FieldDecision {
  return direction === 'google_to_nabatable' ? 'pull_from_google' : 'push_to_google';
}

export function formatValuePreview(value: unknown): string {
  if (value === null || value === undefined || value === '') {
    return 'Not set';
  }

  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    if (value.length === 0) {
      return 'No items';
    }

    if (value.every((entry) => typeof entry === 'string' || typeof entry === 'number')) {
      const joined = value.map(String).join(', ');
      return joined.length > 120 ? `${value.length} items` : joined;
    }

    return `${value.length} items`;
  }

  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return 'Structured value';
  }
}

export function isStructuredValue(value: unknown): boolean {
  return typeof value === 'object' && value !== null;
}

export function humanFieldLabel(item: Pick<GoogleBusinessProfileDraftItem, 'fieldKey' | 'label'>) {
  const weekly = /^operatingHours\.weekly\.(\d+)$/.exec(item.fieldKey);
  if (weekly) {
    const day = formatGbpDay(Number(weekly[1]));
    return day ? `${day} opening hours` : item.label;
  }

  const override = /^operatingHours\.override\.(.+)$/.exec(item.fieldKey);
  if (override) {
    return `Special hours ${override[1]}`;
  }

  const service = /^servicePeriods\.([^.]+)\.(.+)$/.exec(item.fieldKey);
  if (service) {
    const [, dayPart, option] = service;
    const optionLabel = capitalize(option);
    if (dayPart === 'all') {
      return `${optionLabel} (all days)`;
    }
    const day = formatGbpDay(Number(dayPart));
    return day ? `${day} ${option.toLowerCase()}` : item.label;
  }

  return item.label;
}

export function isEmptyValue(value: unknown): boolean {
  if (value === null || value === undefined) {
    return true;
  }

  if (typeof value === 'string') {
    return value.trim().length === 0;
  }

  if (Array.isArray(value)) {
    return value.length === 0;
  }

  return false;
}

export function deriveInitialFieldDecisions(
  draft: GoogleBusinessProfileWorkflowDraft | null,
): Record<string, FieldDecision> {
  if (!draft) {
    return {};
  }

  if (isReadOnlyReviewStatus(draft.status)) {
    return Object.fromEntries(
      draft.sectionDiffs.flatMap((section) =>
        section.items.map((item) => [item.fieldKey, 'keep_nabatable' as const]),
      ),
    );
  }

  return Object.fromEntries(
    draft.sectionDiffs.flatMap((section) =>
      section.items.map((item) => {
        if (!isChangedItem(item)) {
          return [item.fieldKey, 'keep_nabatable' as const];
        }

        if (draft.selectedApprovals[item.fieldKey] && item.canPublishToNabatable) {
          return [item.fieldKey, 'pull_from_google' as const];
        }

        if (!item.canPublishToNabatable && !item.canPushToGoogle) {
          return [item.fieldKey, 'manual' as const];
        }

        return [item.fieldKey, 'keep_nabatable' as const];
      }),
    ),
  );
}

export function getFieldDecision(
  item: GoogleBusinessProfileDraftItem,
  decisions: Record<string, FieldDecision>,
): FieldDecision {
  return decisions[item.fieldKey] ?? 'keep_nabatable';
}

export function buildSelectedApprovalsForDirection(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
  direction: SyncPublishDirection,
): Record<string, boolean> {
  if (!draft) {
    return {};
  }

  if (isReadOnlyReviewStatus(draft.status)) {
    return Object.fromEntries(
      draft.sectionDiffs.flatMap((section) =>
        section.items.map((item) => [item.fieldKey, false] as const),
      ),
    );
  }

  return Object.fromEntries(
    draft.sectionDiffs.flatMap((section) =>
      section.items.map((item) => [
        item.fieldKey,
        isChangedItem(item) &&
          supportsDirection(item, direction) &&
          decisionMatchesDirection(getFieldDecision(item, decisions), direction),
      ]),
    ),
  );
}

export function buildDirectionStats(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
  direction: SyncPublishDirection,
): DirectionStats {
  if (!draft || isReadOnlyReviewStatus(draft.status)) {
    return { selectedCount: 0, actionableCount: 0, blockedCount: 0, ignoredCount: 0 };
  }

  let selectedCount = 0;
  let actionableCount = 0;
  let blockedCount = 0;
  let ignoredCount = 0;

  for (const section of draft.sectionDiffs) {
    for (const item of section.items) {
      if (!isChangedItem(item)) {
        continue;
      }

      const decision = getFieldDecision(item, decisions);
      if (supportsDirection(item, direction) && section.status !== 'stale') {
        actionableCount += 1;
      } else {
        blockedCount += 1;
      }

      if (decision === 'ignore_suggestion') {
        ignoredCount += 1;
      }

      if (
        section.status !== 'stale' &&
        supportsDirection(item, direction) &&
        decisionMatchesDirection(decision, direction)
      ) {
        selectedCount += 1;
      }
    }
  }

  return { selectedCount, actionableCount, blockedCount, ignoredCount };
}

export function buildDirectionSectionSummaries(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
  direction: SyncPublishDirection,
): DirectionSectionSummary[] {
  if (!draft || isReadOnlyReviewStatus(draft.status)) {
    return [];
  }

  return draft.sectionDiffs
    .map((section) => {
      const changedItems = section.items.filter(isChangedItem);
      let actionableCount = 0;
      let selectedCount = 0;
      let oppositeDirectionCount = 0;
      let blockedCount = 0;
      let ignoredCount = 0;

      for (const item of changedItems) {
        const decision = getFieldDecision(item, decisions);
        const matchesDirection = decisionMatchesDirection(decision, direction);
        const matchesOpposite = decisionMatchesDirection(decision, oppositeDirection(direction));
        const supported = supportsDirection(item, direction) && section.status !== 'stale';

        if (supported) {
          actionableCount += 1;
        } else {
          blockedCount += 1;
        }

        if (matchesDirection && supported) {
          selectedCount += 1;
        }

        if (matchesOpposite) {
          oppositeDirectionCount += 1;
        }

        if (decision === 'ignore_suggestion') {
          ignoredCount += 1;
        }
      }

      return {
        section,
        changedItems,
        actionableCount,
        selectedCount,
        oppositeDirectionCount,
        blockedCount,
        ignoredCount,
        unchangedCount: section.items.length - changedItems.length,
      } satisfies DirectionSectionSummary;
    })
    .filter((summary) => summary.changedItems.length > 0 || summary.section.status === 'stale');
}

export function buildSelectedItemsForDirection(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
  direction: SyncPublishDirection,
): Array<GoogleBusinessProfileDraftItem & { sectionLabel: string }> {
  if (!draft || isReadOnlyReviewStatus(draft.status)) {
    return [];
  }

  return draft.sectionDiffs.flatMap((section) =>
    section.items
      .filter(
        (item) =>
          isChangedItem(item) &&
          section.status !== 'stale' &&
          supportsDirection(item, direction) &&
          decisionMatchesDirection(getFieldDecision(item, decisions), direction),
      )
      .map((item) => ({ ...item, sectionLabel: section.label })),
  );
}

export function countSelectionsByDirection(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
): Record<SyncPublishDirection, number> {
  return {
    google_to_nabatable: buildSelectedItemsForDirection(draft, decisions, 'google_to_nabatable')
      .length,
    nabatable_to_google: buildSelectedItemsForDirection(draft, decisions, 'nabatable_to_google')
      .length,
  };
}

export function hasMixedDirectionSelections(
  draft: GoogleBusinessProfileWorkflowDraft | null,
  decisions: Record<string, FieldDecision>,
): boolean {
  const counts = countSelectionsByDirection(draft, decisions);
  return counts.google_to_nabatable > 0 && counts.nabatable_to_google > 0;
}

export function compareBooleanRecords(
  left: Record<string, boolean>,
  right: Record<string, boolean>,
): boolean {
  const keys = new Set([...Object.keys(left), ...Object.keys(right)]);
  for (const key of keys) {
    if (Boolean(left[key]) !== Boolean(right[key])) {
      return false;
    }
  }
  return true;
}

export function workflowStatusVariant(
  status: string,
): 'default' | 'secondary' | 'outline' | 'destructive' {
  if (status === 'published') {
    return 'default';
  }
  if (status === 'failed' || status === 'google_failed' || status === 'stale') {
    return 'destructive';
  }
  if (status === 'partially_published' || status === 'preflight_ready') {
    return 'secondary';
  }
  return 'outline';
}

export function formatWorkflowStatus(status: string): string {
  switch (status) {
    case 'review_ready':
      return 'Ready to review';
    case 'approved':
      return 'Reviewed';
    case 'publishing':
      return 'Applying';
    case 'published':
      return 'Applied';
    case 'partially_published':
      return 'Partly applied';
    case 'google_failed':
      return 'Google update failed';
    case 'preflight_ready':
      return 'Final check passed';
    case 'failed':
      return 'Failed';
    case 'stale':
      return 'Refresh required';
    default:
      return status.replaceAll('_', ' ');
  }
}

export function formatAuditFlowLabel(event: GoogleBusinessProfileWorkflow['auditEvents'][number]) {
  if (event.direction === 'push_from_nabatable_to_google') {
    return 'Nabatable → Google';
  }

  return 'Google → Nabatable';
}

export function itemEligibilityLabel(item: GoogleBusinessProfileDraftItem): string {
  if (item.canPublishToNabatable && item.canPushToGoogle) {
    return 'Two-way action';
  }
  if (item.canPublishToNabatable) {
    return 'Can update Nabatable';
  }
  if (item.canPushToGoogle) {
    return 'Can update Google';
  }
  return 'Needs manual update';
}

export function itemChangeLabel(item: GoogleBusinessProfileDraftItem): string {
  if (isEmptyValue(item.currentValue) && !isEmptyValue(item.providerValue)) {
    return 'Only in Google';
  }

  if (!isEmptyValue(item.currentValue) && isEmptyValue(item.providerValue)) {
    return 'Only in Nabatable';
  }

  return 'Values differ';
}

export function itemActionLabel(
  item: GoogleBusinessProfileDraftItem,
  direction: SyncPublishDirection,
): string {
  const hasCurrent = !isEmptyValue(item.currentValue);
  const hasGoogle = !isEmptyValue(item.providerValue);

  if (direction === 'google_to_nabatable') {
    if (!hasCurrent && hasGoogle) {
      return 'Create in Nabatable';
    }
    if (hasCurrent && !hasGoogle) {
      return 'Remove from Nabatable';
    }
    return 'Update Nabatable';
  }

  if (hasCurrent && !hasGoogle) {
    return 'Create in Google';
  }
  if (!hasCurrent && hasGoogle) {
    return 'Remove from Google';
  }
  return 'Update Google';
}

export function decisionLabel(decision: FieldDecision): string {
  switch (decision) {
    case 'pull_from_google':
      return 'Use Google value';
    case 'push_to_google':
      return 'Send to Google';
    case 'ignore_suggestion':
      return 'Ignored';
    case 'manual':
      return 'Manual';
    case 'keep_nabatable':
    default:
      return 'Keep Nabatable';
  }
}

export function decisionLabelForItem(
  item: GoogleBusinessProfileDraftItem,
  decision: FieldDecision,
): string {
  switch (decision) {
    case 'pull_from_google':
      return itemActionLabel(item, 'google_to_nabatable');
    case 'push_to_google':
      return itemActionLabel(item, 'nabatable_to_google');
    default:
      return decisionLabel(decision);
  }
}

export function itemActionDisabledReason(
  item: GoogleBusinessProfileDraftItem,
  section: GoogleBusinessProfileDraftSection,
  decision: FieldDecision,
  googlePushEnabled = true,
): string | null {
  if (section.status === 'stale') {
    return 'Check for changes again before changing this section.';
  }

  if (decision === 'pull_from_google' && !item.canPublishToNabatable) {
    return 'This field cannot be changed in Nabatable from this review yet.';
  }

  if (decision === 'push_to_google' && !item.canPushToGoogle) {
    return 'This field cannot be changed in Google from this review yet.';
  }

  if (decision === 'push_to_google' && !googlePushEnabled) {
    return 'Google updates are disabled for this linked Business Profile location.';
  }

  if (decision === 'manual') {
    return 'Handle this field outside this review, then check for changes again.';
  }

  return null;
}

