      {detail ? <p className="mt-1 text-xs text-muted-foreground">{detail}</p> : null}
    </div>
  );
}

export function SyncStatusHeader({
  connection,
  workflow,
  manageOnGoogleHref,
  onGenerateDraft,
  onChangeLocation,
  isGeneratingDraft,
  showChangeLocation,
}: SyncStatusHeaderProps) {
  const connectionBadge = connectionStatusBadge(connection.status);
  const draft = workflow?.latestDraft ?? null;
  const activePublishJob = workflow?.activePublishJob ?? null;
  const lastCheckedAt = draft?.fetchedAt ?? connection.lastPullAt;
  const publishUpdatedAt = activePublishJob?.updatedAt ?? draft?.publishedAt ?? null;

  return (
    <Card className="border-border/70 shadow-sm">
      <CardHeader className="gap-4 border-b bg-muted/20">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div className="space-y-3">
            <div className="flex flex-wrap items-center gap-2">
              <CardTitle className="text-xl">Google profile changes</CardTitle>
              <StatusBadge tone={connectionBadge.tone} label={connectionBadge.label} />
              {draft ? (
                <Badge variant={workflowStatusVariant(draft.status)}>
                  {formatWorkflowStatus(draft.status)}
                </Badge>
              ) : null}
              {activePublishJob ? (
                <Badge variant={workflowStatusVariant(activePublishJob.status)}>
                  {formatWorkflowStatus(activePublishJob.status)}
                </Badge>
              ) : null}
            </div>
            <div className="space-y-1 text-sm text-muted-foreground">
              <p>
                Review differences between Google Business Profile and Nabatable before applying
                changes.
              </p>
              <p>
                Linked location:{' '}
                <span className="font-medium text-foreground">
                  {connection.externalLocationTitle ?? connection.externalLocationId ?? 'Unknown'}
                </span>
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Button type="button" onClick={onGenerateDraft} disabled={isGeneratingDraft}>
              <RefreshCcw
                className={isGeneratingDraft ? 'mr-2 size-4 animate-spin' : 'mr-2 size-4'}
              />
              {isGeneratingDraft ? 'Checking…' : 'Check for changes'}
            </Button>
            {manageOnGoogleHref ? (
              <Button type="button" variant="outline" asChild>
                <a href={manageOnGoogleHref} target="_blank" rel="noreferrer">
                  <ExternalLink className="mr-2 size-4" />
                  View on Google Maps
                </a>
              </Button>
            ) : null}
            {showChangeLocation ? (
              <Button type="button" variant="ghost" onClick={onChangeLocation}>
                <PencilLine className="mr-2 size-4" />
                Change location
              </Button>
            ) : null}
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4 p-4">
        {connection.status === 'sync_error' && connection.lastError ? (
          <Alert variant="destructive">
            <AlertTitle>Connection needs attention</AlertTitle>
            <AlertDescription>{connection.lastError}</AlertDescription>
          </Alert>
        ) : null}

        {draft?.staleSections.length ? (
          <Alert variant="destructive">
            <AlertTitle>Check for changes again</AlertTitle>
            <AlertDescription>
              These sections changed since the review was prepared: {draft.staleSections.join(', ')}
              .
            </AlertDescription>
          </Alert>
        ) : null}

        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <MetricCard
            label="Last checked"
            value={formatGbpDateTime(lastCheckedAt) ?? 'Not checked yet'}
            detail="Latest Google profile details compared with Nabatable"
          />
          <MetricCard
            label="Latest review"
            value={draft ? formatWorkflowStatus(draft.status) : 'No review yet'}
            detail={
              draft?.approvedAt
                ? `Reviewed ${formatGbpDateTime(draft.approvedAt)}`
                : 'Check for changes to begin review'
            }
          />
          <MetricCard
            label="Active update"
            value={
              activePublishJob
                ? publishDirectionLabel(activePublishJob.directionIntent)
                : 'No active update'
            }
            detail={
              activePublishJob
                ? `${formatWorkflowStatus(activePublishJob.status)} · ${formatGbpDateTime(publishUpdatedAt) ?? 'No timestamp'}`
                : 'No update in progress'
            }
          />
          <MetricCard
            label="Change history"
            value={`${workflow?.auditEvents.length ?? 0} update${workflow?.auditEvents.length === 1 ? '' : 's'}`}
            detail={workflow?.blockedReasons[0] ?? 'Recent review decisions and results'}
          />
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import { ArrowRightLeft, GitPullRequestArrow, Send } from 'lucide-react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';

import {
  SYNC_DIRECTION_OPTIONS,
  type DirectionStats,
  type SyncPublishDirection,
} from '../lib/sync-review';

type SyncDirectionTabsProps = {
  direction: SyncPublishDirection;
  onDirectionChange: (direction: SyncPublishDirection) => void;
  stats: Record<SyncPublishDirection, DirectionStats>;
  hasMixedSelections: boolean;
  googlePushEnabled: boolean;
};

export function SyncDirectionTabs({
  direction,
  onDirectionChange,
  stats,
  hasMixedSelections,
  googlePushEnabled,
}: SyncDirectionTabsProps) {
  return (
    <div className="space-y-3">
      <Tabs
        value={direction}
        onValueChange={(value) => onDirectionChange(value as SyncPublishDirection)}
      >
        <TabsList className="grid h-auto w-full grid-cols-1 gap-1 bg-transparent p-0 md:grid-cols-2">
          {SYNC_DIRECTION_OPTIONS.map((option) => {
            const directionStats = stats[option.value];
            const Icon = option.value === 'google_to_nabatable' ? GitPullRequestArrow : Send;

            return (
              <TabsTrigger
                key={option.value}
                value={option.value}
                disabled={option.value === 'nabatable_to_google' && !googlePushEnabled}
                className="h-auto items-start justify-between rounded-lg border border-border/70 bg-background px-4 py-3 text-left data-[state=active]:border-foreground/20 data-[state=active]:shadow-sm"
                data-testid={`gbp-direction-tab-${option.value}`}
              >
                <span className="flex items-start gap-3">
                  <Icon className="mt-0.5 size-4" />
                  <span className="space-y-1">
                    <span className="block text-sm font-semibold text-foreground">
                      {option.label}
                    </span>
                    <span className="block text-xs font-normal text-muted-foreground">
                      {option.description}
                    </span>
                  </span>
                </span>
                <span className="flex flex-col items-end gap-1 text-xs text-muted-foreground">
                  <Badge variant="secondary" className="tabular-nums">
                    {directionStats.selectedCount}/{directionStats.actionableCount}
                  </Badge>
                  {directionStats.blockedCount > 0 ? (
                    <span>{directionStats.blockedCount} blocked</span>
                  ) : null}
                </span>
              </TabsTrigger>
            );
          })}
        </TabsList>
      </Tabs>

      {hasMixedSelections ? (
        <Alert>
          <ArrowRightLeft className="size-4" />
          <AlertTitle>Apply one update path at a time</AlertTitle>
          <AlertDescription>
            You have chosen changes for both paths. Run the final check and apply the current tab,
            then switch tabs for the other path.
          </AlertDescription>
        </Alert>
      ) : null}
    </div>
  );
}

